mapper.select:
SELECT * FROM oa_knowledge_doc_version
WHERE tenant_id = #{tenantId} AND document_id = #{documentId} AND id = #{versionId}
    AND deleted = 0 AND publish_time IS NOT NULL

mapper.update:
UPDATE oa_knowledge_document SET external_visible_flag = #{visible}, external_version_id = #{versionId},
    external_attachment_file_ids = #{attachmentFileIds},
    version = version + 1, update_by = #{document.updateBy}, update_time = #{document.updateTime}
WHERE tenant_id = #{document.tenantId} AND document_id = #{document.documentId}
    AND version = #{document.version} AND deleted = 0
